contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, address target, uint idx) public payable {
        require(address(this).balance >= amount, "not enough balance");

        uint beforeCount = c.depositsCount();
        address payable ownerAddr = payable(c.owner());

        // The test contract is the owner of the freshly deployed c.
        require(ownerAddr == address(this), "test must own c");

        // Revert rules: a non-owner must never be able to withdraw or send.
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, amount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Since msg.sender (the test contract) is owner, these should all succeed:
        // none of these reverted.
        bool allSucceeded = !withdrawAllReverted && !withdrawReverted && !sendMoneyReverted;

        uint afterCount = c.depositsCount();

        // The fallback always increments depositsCount, regardless of value.
        // We can observe this by sending a value call and checking the counter goes up.
        bool fallbackReverted;
        (bool fbSuccess, ) = address(c).call{value: amount}("");
        fallbackReverted = !fbSuccess;
        uint finalCount = c.depositsCount();

        assert(allSucceeded && fallbackReverted == false && finalCount == beforeCount + 1);
    }

    receive() external payable {}
    fallback() external payable {}
}

