        uint withdrawAfterBalance = address(c).balance;

        assert(
            withdrawReverted
                ? withdrawAfterBalance == withdrawBeforeBalance
                : withdrawAfterBalance == withdrawBeforeBalance - _withdrawAmount
        );
    }

    receive() external payable {}
}

