    constructor(C _c) { c = _c; }

    function run(bool owner, bool which, uint amount) public payable {
        require(address(this).balance >= amount);
        require(address(c).balance >= amount);

        if (owner) {
            address payable ap = payable(c.owner());
            (bool ok, ) = ap.call{value: 0}("");
        }

        uint beforeBalance = address(c).balance;
        bool reverted = true;
        if (which) {
            if (owner) {
                (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));
                reverted = !ok;
            } else {
                (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("withdraw(uint256)", amount));
                reverted = !ok;
            }
        } else {
            if (owner) {
                (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
                reverted = !ok;
            } else {
                (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("withdrawAll()"));
                reverted = !ok;
            }
        }

        if (reverted || !owner || amount > beforeBalance) {
            assert(!reverted ? address(c).balance == beforeBalance - (which ? amount : beforeBalance) : beforeBalance == address(c).balance);
        } else {
            assert(address(c).balance == beforeBalance - (which ? amount : beforeBalance));
        }
    }

    receive() external payable {}
    fallback() external payable {}
}

