        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.sendMoney(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: for a non-owner caller, a value transfer must not silently
        // reduce C's balance; either it reverts, or C's balance decreases by exactly
        // the forwarded amount. Additionally, depositsCount changes by at most one
        // per accepted fallback deposit and never decreases.
        assert(
            (reverted && balAfter == balBefore && depositsAfter == depositsBefore)
            ||
            (!reverted && balBefore >= balAfter && balBefore - balAfter == amount && depositsAfter >= depositsBefore && depositsAfter - depositsBefore <= 1)
        );
    }
}

